func MixedPickupEventLoadBody(r *TableReader, value *MixedPickupEvent) bool {
	MixedPickupEventReset(value)
	for {
		ref, ok := r.lebPair()
		if !ok {
			ref, ok = r.lebWide()
		}
		if !ok {
			r.Report.Malformed = true
			return false
		}
		if ref == 0 {
			return true
		}
		fieldID, ok := r.Resolve(ref)
		if !ok || !r.Has(1) {
			r.Report.Malformed = true
			return false
		}
		if fieldID == 0xfffffffffffffffe || fieldID == 0xfffffffffffffffd || r.Nested && fieldID == 0xffffffffffffffff {
			r.Report.Malformed = true
			return false
		}
		kind := r.Get8()
		switch fieldID {
		case 0x9e7fd06d864fbd56: // item_id
			if kind != 7 {
				if tableKindWidens(kind, 7) {
					if !r.Has(tableKindBytes(kind)) {
						r.Report.Malformed = true
						return false
					}
					{
						v := r.Unsigned(kind)
						if v > 1023 {
							v = 1023
							r.Report.Clamped++
						}
						value.ItemId = uint32(v)
					}
					r.Report.Widened++
					break
				}
				r.Report.KindMismatch++
				if !r.Skip(kind) {
					r.Report.Malformed = true
					return false
				}
				break
			}
			if !r.Has(2) {
				r.Report.Malformed = true
				return false
			}
			{
				v := r.Get16()
				if v > 1023 {
					v = 1023
					r.Report.Clamped++
				}
				value.ItemId = uint32(v)
			}
		case 0x8113fe7ea2b16969: // amount
			if kind != 4 {
				if tableKindWidens(kind, 4) {
					if !r.Has(tableKindBytes(kind)) {
						r.Report.Malformed = true
						return false
					}
					{
						v := r.Signed(kind)
						if v < 0 {
							v = 0
							r.Report.Clamped++
						} else if v > 255 {
							v = 255
							r.Report.Clamped++
						}
						value.Amount = int32(v)
					}
					r.Report.Widened++
					break
				}
				r.Report.KindMismatch++
				if !r.Skip(kind) {
					r.Report.Malformed = true
					return false
				}
				break
			}
			if !r.Has(4) {
				r.Report.Malformed = true
				return false
			}
			{
				v := int32(r.Get32())
				if v < 0 {
					v = 0
					r.Report.Clamped++
				} else if v > 255 {
					v = 255
					r.Report.Clamped++
				}
				value.Amount = int32(v)
			}
		default:
			r.Report.Unknown++
			if !r.Skip(kind) {
				r.Report.Malformed = true
				return false
			}
		}
	}
}

func MixedPickupEventLoad(value *MixedPickupEvent, data []byte, report *TableReport) bool {
	if report == nil {
		var ignored TableReport
		report = &ignored
	}
	r, verdict := tableOpen(data, report)
	report.Verdict = verdict
	report.Reason = ""
	if verdict == TableOpenRefused {
		report.Reason = "unsupported wire form"
		if len(data) > 0 && data[0] == 2 {
			report.Reason = "message form requires an announced vocabulary and a message reader"
		}
	}
	if verdict != TableOpenOk {
		MixedPickupEventReset(value)
		if verdict == TableOpenDamaged {
			report.Malformed = true
		}
		return false
	}
	// The root read answers its own early end after the walk, not before it.
	// A body that returned at its zero reference left the cursor on the byte
	// after that reference. Every field leaves the cursor where skip would, so
	// r.Offset != len(r.Buffer) is the old EndsEarly on the true path.
	// Nothing is decoded on the damaged path: the value goes back to defaults
	// and the report goes back to what the caller handed in, so an early end
	// counts no unknown, no kind mismatch and no clamp — as when the framing
	// walk refused before the reader had seen one byte.
	before := *report
	if !MixedPickupEventLoadBody(&r, value) {
		// The reading walk stops on rules the framing walk has no opinion about
		// — a reserved id in a file body is the one that matters — so a body
		// that stopped is still asked the framing question from the start of
		// the body, and a body whose framing ends early is damage whatever else
		// was wrong with it.
		probe := r
		probe.Offset = 0
		if probe.EndsEarly() {
			MixedPickupEventReset(value)
			*report = before
			report.Malformed = true
			report.Verdict = TableOpenDamaged
			return false
		}
		report.Verdict = TableOpenBodyStopped
		return false
	}
	if r.Offset != int64(len(r.Buffer)) {
		MixedPickupEventReset(value)
		*report = before
		report.Malformed = true
		report.Verdict = TableOpenDamaged
		return false
	}
	return true
}

func MixedPickupEventSaveMessageBody(w *TableMessageWriter, value *MixedPickupEvent) bool {
	{
		if value.ItemId != 0 {
			w.Put(49, TableMessageRefBitsHere)
			tableMessageWriteScalar(&w.TableBitWriter, TableMessageShape{Kind: 7, Packing: 1, Bits: 10, Base: [2]uint64{0x0, 0x0}, Min: 0, Max: 0, QMin: math.Float32frombits(0x0), QDelta: math.Float32frombits(0x0), QCount: 0}, uint64(value.ItemId), uint64(0))
		}
	}
	{
		if value.Amount != 0 {
			w.Put(50, TableMessageRefBitsHere)
			tableMessageWriteScalar(&w.TableBitWriter, TableMessageShape{Kind: 4, Packing: 1, Bits: 8, Base: [2]uint64{0x0, 0x0}, Min: 0, Max: 0, QMin: math.Float32frombits(0x0), QDelta: math.Float32frombits(0x0), QCount: 0}, uint64(value.Amount), uint64(0))
		}
	}
	w.Put(0, TableMessageRefBitsHere)
	return !w.Overflow
}
func MixedPickupEventMeasureMessages(values []*MixedPickupEvent) int64 {
	if len(values) < 1 || len(values) > TableMessageBatchMax {
		return -1
	}
	w := TableMessageWriter{TableBitWriter: TableBitWriter{Measuring: true}}
	for _, value := range values {
		if value == nil || !MixedPickupEventSaveMessageBody(&w, value) {
			return -1
		}
	}
	w.Align()
	if w.Overflow {
		return -1
	}
	return 2 + w.Bits/8
}
func MixedPickupEventSaveMessages(values []*MixedPickupEvent, buffer []byte, report *TableReport) int64 {
	if len(values) < 1 || len(values) > TableMessageBatchMax {
		if report != nil {
			tableMessageRefuse(report, "batch_too_large")
		}
		return -1
	}
	if len(buffer) < 2 {
		return -1
	}
	buffer[0] = 2
	buffer[1] = byte(len(values) - 1)
	w := TableMessageWriter{TableBitWriter: TableBitWriter{Buffer: buffer[2:]}}
	for _, value := range values {
		if value == nil || !MixedPickupEventSaveMessageBody(&w, value) {
			return -1
		}
	}
	w.Align()
	if w.Overflow {
		return -1
	}
	return 2 + w.Bits/8
}
